def merge_gate_commands(text: str) -> dict[str, str]:
    """The per-surface merge-gate commands from AGENTS.md's validation matrix.

    Read from the runbook rather than hardcoded. AGENTS.md calls this matrix
    "what tells `verifier` which ones apply", so the two files have to agree and
    nothing compared them: `verifier` sent web changes to `apps/web quick-ci`,
    which skips the production build that `apps/web ci` adds, while the runbook
    named `apps/web ci` as the gate.
    """
    section = text.split("Every changed surface's merge-gate command", 1)
    if len(section) < 2:
        return {}
    body = section[1].split("\n## ", 1)[0]
    return {
        match.group("surface").strip(): match.group("command").strip()
        for match in re.finditer(
            r"(?m)^- (?P<surface>[^:`]+): `(?P<command>make [^`]+)`", body
        )
    }


def tool_names_in_body(text: str) -> set[str]:
    """Tool names an agent's operating rules tell it to use.

    Backticked only. Prose says "browser automation" and "a browser" constantly;
    an identifier in a code span is the agent being pointed at a specific tool.
    """
    return {
        name
        for name in re.findall(r"`(mcp__[A-Za-z0-9_]+|browser_[a-z_]+)`", text)
    }


def granted_tool_names(tools: list[str]) -> set[str]:
    """Every spelling by which a granted tool can be named.

    An MCP tool is granted by its qualified name but referred to by its bare
    one, so `mcp__plugin_playwright_playwright__browser_navigate` in the
    frontmatter satisfies a body that says `browser_navigate`.
    """
    return set(tools) | {tool.rsplit("__", 1)[-1] for tool in tools}


def compose_services(command: str) -> list[str]:
    """Service names a `docker compose up` invocation starts.

    Flags and make variables are dropped, so the Makefile's
    `$(DOCKER_COMPOSE) up $(E2E_COMPOSE_UP_FLAGS) db chat web` and an agent's
    `docker compose up -d --build db chat web` reduce to the same list.
    """
    _, _, tail = command.partition(" up ")
    if not tail:
        return []
    services = []
    for token in tail.split():
        if token.startswith("-") or token.startswith("$(") or "=" in token:
            continue
        services.append(token)
    return services


def compose_up_line(text: str) -> str:
    for line in text.splitlines():
        if "compose" in line.lower() and " up " in line:
            return line.strip()
    return ""


def confidence_anchors(text: str) -> dict[int, str]:
    return {
        int(match.group(1)): match.group(2)
        for match in re.finditer(r"(?m)^- \*\*(\d+)\*\* — (.+)$", text)
    }


def reporting_thresholds(text: str) -> list[int]:
    """Every score at or above which code-review says it reports a finding."""
    return [
        int(match.group(1))
        for match in re.finditer(r"(?i)(?:at|scores) \*{0,2}(\d+)\*{0,2} or above", text)
    ]


def nested_runbook_paths() -> list[str]:
    """Repository runbooks other than the root one, as written in prose."""
    paths = []
    for directory in find_agent_directories(REPO_ROOT):
        runbook = directory / "AGENTS.md"
        if runbook.exists() and runbook != AGENTS_MD:
            paths.append(str(runbook.relative_to(REPO_ROOT)))
    return sorted(paths)


